begin;
set local timezone='UTC';
do $$
<<recruitment>>
declare owner_id uuid;branch_id uuid;user_id uuid:=gen_random_uuid();unverified uuid:=gen_random_uuid();email text:='recruitment-'||gen_random_uuid()||'@example.invalid';job uuid;app uuid;req uuid:=gen_random_uuid();p jsonb;v jsonb;again jsonb;denied boolean;
begin
 select s.user_id into strict owner_id from public.staff_profiles s where s.role='owner' and s.is_active limit 1;
 select b.branch_id into strict branch_id from public.business_branches b where b.is_active limit 1;
 insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(user_id,'authenticated','authenticated',email,now(),'{}','{"role":"owner"}',now(),now());
 insert into auth.users(id,aud,role,email,phone,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(unverified,'authenticated','authenticated','unverified-'||email,'201000000001','{}','{}',now(),now());
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 v:=public.recruitment_action('save_job',jsonb_build_object('request_id',gen_random_uuid(),'branch_id',branch_id,'title_ar','وظيفة اختبار','title_en','QA role','details_ar','خبرة مناسبة','details_en','Relevant experience','published',true));job:=(v->>'job_id')::uuid;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 v:=public.recruitment_action('jobs','{}');assert exists(select 1 from jsonb_array_elements(v->'jobs') j where j->>'id'=job::text),'Published job missing';assert v::text not like '%'||email||'%','Applicant contacts leaked in jobs';
 denied:=false;begin perform public.recruitment_action('owner_read','{}');exception when insufficient_privilege then denied:=true;end;assert denied,'Anonymous applicant list exposed';
 denied:=false;begin perform 1 from private.recruitment_applications;exception when insufficient_privilege then denied:=true;end;assert denied,'Private applications table exposed';
 denied:=false;begin perform public.recruitment_action('submit',jsonb_build_object('request_id',gen_random_uuid(),'job_id',job,'name','A','email','bad'));exception when raise_exception then denied:=true;end;assert denied,'Invalid application accepted';
 p:=jsonb_build_object('request_id',req,'job_id',job,'name','QA Candidate','email',email,'phone','+201000000001','message','QA experience');v:=public.recruitment_action('submit',p);again:=public.recruitment_action('submit',p);assert v=again,'Anonymous replay changed application';app:=(v->>'application_id')::uuid;
 assert v->>'status'='received' and not(v ? 'email'),'Public receipt contains private review data';
 denied:=false;begin perform public.recruitment_action('submit',p||'{"name":"changed"}');exception when raise_exception then denied:=true;end;assert denied,'Changed payload reused request';
 for i in 1..4 loop perform public.recruitment_action('submit',jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid())));end loop;
 denied:=false;begin perform public.recruitment_action('submit',jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid())));exception when raise_exception then denied:=true;end;assert denied,'Contact daily application limit bypassed';
 perform set_config('request.jwt.claim.sub',user_id::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.recruitment_action('review',jsonb_build_object('request_id',gen_random_uuid(),'application_id',app,'status','accepted'));exception when insufficient_privilege then denied:=true;end;assert denied,'User metadata owner granted hiring access';
 denied:=false;begin perform public.recruitment_action('activate_employee',jsonb_build_object('request_id',gen_random_uuid(),'application_id',app));exception when insufficient_privilege then denied:=true;end;assert denied,'Applicant activated self';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.recruitment_action('review',jsonb_build_object('request_id',gen_random_uuid(),'application_id',app,'status','interview','interview_at',now()+interval '1 day','owner_note','Private interview note'));
 perform public.recruitment_action('review',jsonb_build_object('request_id',gen_random_uuid(),'application_id',app,'status','accepted'));
 execute 'reset role';assert (select owner_note from private.recruitment_applications where id=app)='Private interview note','Review transition erased interview note';assert not exists(select 1 from public.staff_profiles s where s.user_id=recruitment.user_id),'Acceptance auto-granted staff';execute 'set local role authenticated';
 p:=jsonb_build_object('request_id',gen_random_uuid(),'application_id',app,'user_id',unverified,'branch_id',branch_id,'salary',5000,'commission_percent',8,'currency','EGP','starts_on',current_date);
 denied:=false;begin perform public.recruitment_action('prepare_employee',p);exception when raise_exception then denied:=true;end;assert denied,'Unverified account matched application';
 execute 'reset role';
 update auth.users set phone_confirmed_at=now() where id=unverified;
 insert into public.staff_profiles(user_id,full_name,role,permissions,is_active) values(unverified,'Existing inactive fixture','employee','{}',false);
 execute 'set local role authenticated';
 denied:=false;begin perform public.recruitment_action('prepare_employee',jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid())));exception when raise_exception then denied:=true;end;assert denied,'Existing inactive staff account overwritten';
 p:=p||jsonb_build_object('request_id',gen_random_uuid(),'user_id',user_id,'currency','AED');
 denied:=false;begin perform public.recruitment_action('prepare_employee',p);exception when raise_exception then denied:=true;end;assert denied,'Non-EGP hiring salary accepted';
 p:=p||jsonb_build_object('request_id',gen_random_uuid(),'currency','EGP');
 denied:=false;begin perform public.recruitment_action('prepare_employee',(p-'salary')||jsonb_build_object('request_id',gen_random_uuid()));exception when not_null_violation then denied:=true;end;assert denied,'Missing explicit salary accepted';
 v:=public.recruitment_action('prepare_employee',p);again:=public.recruitment_action('prepare_employee',p);assert v=again,'Preparation replay changed employee';
 execute 'reset role';
 assert exists(select 1 from public.staff_profiles s where s.user_id=recruitment.user_id and s.role='employee' and not s.is_active and s.permissions='{}'),'Preparation must be inactive without permissions';
 assert exists(select 1 from private.hr_employment e where e.staff_id=user_id and e.salary=5000 and e.commission_percent=8 and e.currency='EGP'),'Explicit compensation missing';
 perform set_config('request.jwt.claim.sub',user_id::text,true);execute 'set local role authenticated';
 assert private.active_staff_role() is null,'Prepared employee has effective active role';
 denied:=false;begin perform public.hr_action('read','{}');exception when insufficient_privilege then denied:=true;end;assert denied,'Prepared employee accessed staff HR';
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner_id::text,true);
 update auth.users set email='changed-'||recruitment.email where id=user_id;
 execute 'set local role authenticated';denied:=false;begin perform public.recruitment_action('activate_employee',jsonb_build_object('request_id',gen_random_uuid(),'application_id',app));exception when raise_exception then denied:=true;end;assert denied,'Activation accepted changed verified contact';
 execute 'reset role';update auth.users set email=recruitment.email where id=user_id;execute 'set local role authenticated';
 p:=jsonb_build_object('request_id',gen_random_uuid(),'application_id',app);v:=public.recruitment_action('activate_employee',p);assert v=public.recruitment_action('activate_employee',p),'Activation replay changed result';
 execute 'reset role';assert exists(select 1 from public.staff_profiles s where s.user_id=recruitment.user_id and s.role='employee' and s.is_active and s.permissions='{}'),'Explicit owner activation failed';
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',user_id::text,true);
 denied:=false;begin perform public.recruitment_action('owner_read','{}');exception when insufficient_privilege then denied:=true;end;assert denied,'New employee read applicant PII';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.recruitment_action('save_job',jsonb_build_object('request_id',gen_random_uuid(),'id',job,'branch_id',branch_id,'title_ar','وظيفة اختبار','title_en','QA role','details_ar','خبرة مناسبة','details_en','Relevant experience','published',false));
 execute 'set local role anon';perform set_config('request.jwt.claim.sub','',true);
 denied:=false;begin perform public.recruitment_action('submit',jsonb_build_object('request_id',gen_random_uuid(),'job_id',job,'name','Another candidate','email','another@example.invalid'));exception when raise_exception then denied:=true;end;assert denied,'Closed vacancy accepted application';
 raise notice 'PASS recruitment public jobs, anonymous validation/rate/privacy/idempotency, owner review, verified-account inactive preparation and explicit activation';
end $$;
rollback;
